import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHash } from 'node:crypto';
import { CONFIG_FILES, SOURCE_REPOSITORY, SOURCE_REF } from './config-sync-map.mjs';

const toolDir = dirname(fileURLToPath(import.meta.url));
const siteRoot = process.argv[2] ? resolve(process.argv[2]) : resolve(toolDir, '..');
const outPath = resolve(siteRoot, 'assets/js/generated/config-files.js');
const statePath = resolve(siteRoot, 'synced-configs/.sync-state.json');
const state = existsSync(statePath) ? JSON.parse(readFileSync(statePath, 'utf8')) : {};
const files = {};

for (const item of CONFIG_FILES) {
  const path = resolve(siteRoot, item.target);
  if (!existsSync(path)) throw new Error(`Missing website config snapshot: ${item.target}`);
  const content = readFileSync(path, 'utf8').replace(/\r\n/g, '\n');
  files[item.id] = {
    id: item.id,
    type: 'config-file',
    platform: item.platform,
    format: item.format,
    sourcePath: item.source,
    sourceKind: item.sourceKind || 'repository-default',
    websitePath: item.target,
    article: item.article,
    sha256: createHash('sha256').update(content).digest('hex'),
    content
  };
}

const bundle = {
  schemaVersion: 1,
  sourceRepository: SOURCE_REPOSITORY,
  sourceRef: SOURCE_REF,
  sourceCommit: state.sourceCommit || null,
  files
};
writeFileSync(outPath,
  '/* AUTO-GENERATED by tools/build-config-bundle.mjs. Do not edit by hand. */\n' +
  'window.COREX_CONFIG_FILES = ' + JSON.stringify(bundle, null, 2) + ';\n', 'utf8');
console.log(`Wrote ${Object.keys(files).length} files to ${outPath}`);
